WITH ids AS (SELECT id_imovel FROM UNNEST(['BA-2901601-2D6EA3618F4A48BF87E2EB78992B2968','BA-2902005-876B8A8CE62D40119A8446C4262A5AC7','BA-2913705-C31099AB04E24F15B9941AAAF17DC244','BA-2916500-9222A7C0C77E4E019B498875C6578189','BA-2921401-9177991E4861442EACFE3ACDDC06DB91','BA-2926509-E3BCDCD3078C4BADBC80D0166EACCAF6','BA-2928109-0F43ABB998F5484394BAA55A4964A2BD','BA-2929057-2483416C90F94058B15FED07A5FE9FB7','BA-2929057-3DE9EF4059BE416EBC88EAAE603F1B5F','BA-2929057-60EC867CE3FF4AEAA712CD4AE3992CCB','BA-2929057-C5D11EE026A64399A6EF36764E8739E9','BA-2930766-9CCE04D4FED440E0844D0C38B9C89B70','RS-4322301-249321677C5045DC84BE25A36C504F31']) AS id_imovel), rl AS (SELECT r.id_imovel,r.data_extracao,r.geometria FROM `basedosdados.br_sfb_sicar.reserva_legal` r WHERE ((r.data_extracao='2026-08-02' AND STARTS_WITH(r.id_imovel,'BA-')) OR (r.data_extracao='2026-08-01' AND STARTS_WITH(r.id_imovel,'RS-'))) AND r.id_imovel IN (SELECT id_imovel FROM ids)), im AS (SELECT a.id_imovel,a.data_extracao,a.area,a.geometria FROM `basedosdados.br_sfb_sicar.area_imovel` a WHERE a.data_extracao IN ('2026-08-01','2026-08-02') AND a.sigla_uf IN ('BA','RS') AND a.id_imovel IN (SELECT id_imovel FROM ids)), g AS (SELECT rl.id_imovel,MAX(rl.data_extracao) data_extracao,ST_UNION_AGG(rl.geometria) geom_rl FROM rl GROUP BY rl.id_imovel), i AS (SELECT * FROM im QUALIFY ROW_NUMBER() OVER(PARTITION BY id_imovel ORDER BY data_extracao DESC)=1) SELECT g.id_imovel,g.data_extracao,ROUND(ST_AREA(g.geom_rl)/10000,6) area_rl_ha,ROUND(i.area,6) area_imovel_ha,ROUND(ST_AREA(ST_INTERSECTION(g.geom_rl,i.geometria))/10000,6) area_intersecao_ha,ROUND(SAFE_DIVIDE(ST_AREA(ST_INTERSECTION(g.geom_rl,i.geometria)),ST_AREA(g.geom_rl))*100,6) percentual_rl_intersecta_imovel FROM g JOIN i USING(id_imovel) ORDER BY g.id_imovel